class Solution {
    public long makeSubKSumEqual(int[] arr, int k) {
        int n = arr.length, g = gcd(n, k);
        long ans = 0;
        for (int s = 0; s < g; s++) {
            List<Long> cyc = new ArrayList<>();
            int j = s;
            do { cyc.add((long) arr[j]); j = (j + k) % n; } while (j != s);
            Collections.sort(cyc);
            long m = cyc.get(cyc.size() / 2);
            for (long v : cyc) ans += Math.abs(v - m);
        }
        return ans;
    }
    private int gcd(int a, int b) { return b == 0 ? a : gcd(b, a % b); }
}

