    const n = arr.length, g = gcd(n, k);
    let ans = 0;
    for (let s = 0; s < g; s++) {
        const cyc = [];
        let j = s;
        do { cyc.push(BigInt(arr[j])); j = (j + k) % n; } while (j !== s);
        cyc.sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
        const m = cyc[Math.floor(cyc.length / 2)];
        for (const v of cyc) ans += Number(v > m ? v - m : m - v);
    }
    return ans;
};

