class Solution {
    public long makeSubKSumEqual(int[] arr, int k) {
        int n = arr.length, g = gcd(n, k);
        long ans = 0;
        for (int s = 0; s < g; s++) {
            List<Long> cyc = new ArrayList<>();
            int j = s;
            do { cyc.add((long) arr[j]); j = (j + k) % n; } while (j != s);
            long m = quickSelect(cyc, cyc.size() / 2);
            for (long v : cyc) ans += Math.abs(v - m);
        }
        return ans;
    }
    private long quickSelect(List<Long> a, int t) {
        List<Long> pivots = new ArrayList<>();
        for (long v : a) if (a.size() <= 5 || Math.random() < 0.2) pivots.add(v);
        Collections.sort(pivots);
        long p = pivots.get(pivots.size() / 2);
        List<Long> lo = new ArrayList<>(), eq = new ArrayList<>(), hi = new ArrayList<>();
        for (long v : a) { if (v < p) lo.add(v); else if (v == p) eq.add(v); else hi.add(v); }
        if (t < lo.size()) return quickSelect(lo, t);
        if (t < lo.size() + eq.size()) return p;
        return quickSelect(hi, t - lo.size() - eq.size());
    }
    private int gcd(int a, int b) { return b == 0 ? a : gcd(b, a % b); }
}

